
# R reference values for gaply_core::stats_dist's exact distribution of the
# Mann-Whitney statistic (Research OS, Phase 8Y-1, decision 603), the exact
# p of stats.analyze.independent_ranks.
#
# Run by its full path, from anywhere:
#
#   /usr/local/bin/Rscript make_ranks_dist_fixtures.R
#
# R is the reference, run outside Gaply (ADR-008): nothing of R is copied into
# Gaply. Base R only (stats). make_dist_fixtures.R and
# make_xtab_dist_fixtures.R are separate scripts and are not run by this one,
# so their files are untouched. Writes, next to this script, one file with a
# '#' header naming this script, R's version and the call, then a CSV body
# with every number as %.17g:
#
#   wilcox_p.csv  n1,n2,u,lower,upper   lower = pwilcox(u, n1, n2)
#                                       upper = pwilcox(u - 1, n1, n2, lower.tail = FALSE)
#
# so lower is P(U <= u) and upper is P(U >= u), U being the number of pairs
# (x, y), x from the first group of n1 values and y from the second of n2,
# with x above y, when no two values are tied: R's W.
#
# n1 and n2 each among 1, 2, 3, 5, 10, 20, 35 and 49. When n1 + n2 is at most
# 20, every u from 0 to n1 n2; otherwise u at 0, 1, 2, the centre (both
# integers next to n1 n2 / 2), n1 n2 - 2, n1 n2 - 1, n1 n2, and nine points
# spread evenly between.
#
# Synthetic grids only. No manuscript or data of anyone's is read.

args <- commandArgs(trailingOnly = FALSE)
script <- sub("^--file=", "", args[grep("^--file=", args)])
here <- dirname(normalizePath(script))

f17 <- function(x) sprintf("%.17g", as.numeric(x))

sizes <- c(1, 2, 3, 5, 10, 20, 35, 49)
out <- list()
for (n1 in sizes) for (n2 in sizes) {
  top <- n1 * n2
  if (n1 + n2 <= 20) {
    u <- 0:top
  } else {
    u <- c(0, 1, 2, floor(top / 2), ceiling(top / 2), top - 2, top - 1, top,
           round(seq(0, top, length.out = 11))[2:10])
    u <- sort(unique(u[u >= 0 & u <= top]))
  }
  out[[length(out) + 1]] <- data.frame(
    n1 = f17(n1), n2 = f17(n2), u = f17(u),
    lower = f17(pwilcox(u, n1, n2)),
    upper = f17(pwilcox(u - 1, n1, n2, lower.tail = FALSE)))
}
frame <- do.call(rbind, out)

path <- file.path(here, "wilcox_p.csv")
writeLines(c(
  "# R's exact distribution of the Mann-Whitney statistic, for gaply_core::stats_dist (Research OS, Phase 8Y-1).",
  "# Generated by /usr/local/bin/Rscript make_ranks_dist_fixtures.R (do not edit by hand).",
  sprintf("# %s, %s; lower = pwilcox(u, n1, n2), upper = pwilcox(u - 1, n1, n2, lower.tail = FALSE).",
          R.version.string, R.version$arch)), path)
write.table(frame, path, sep = ",", quote = FALSE, row.names = FALSE, append = TRUE)
cat(sprintf("wilcox_p.csv: %d rows\n", nrow(frame)))
